163	/**
164	 * Hands full chunks to the local recording store while the episode is still
165	 * running, so a long game is not stuck in the browser journal until it ends.
166	 * Sealed chunks are byte-stable, so the store treats the eventual final
167	 * submit of the same chunk ids as a no-op.
168	 */
169	const FLUSH_INTERVAL_MS = 5_000;
170	let flushTimer: number | undefined;
171	
172	/**
173	 * Sealing replays the whole journal, so coalesce bursts of input (a gravity
174	 * tick arrives several times a second) onto a slow timer.
175	 */
176	function scheduleTraceFlush(trace: StoredOverlayTrace): void {
177	  if (flushTimer !== undefined) return;
178	  flushTimer = window.setTimeout(() => {
179	    flushTimer = undefined;
180	    if (activeTrace === trace) flushSealedTrace(trace);
181	  }, FLUSH_INTERVAL_MS);
182	}
183	
184	function cancelTraceFlush(): void {
185	  if (flushTimer !== undefined) window.clearTimeout(flushTimer);
186	  flushTimer = undefined;
187	}
188	
189	function flushSealedTrace(trace: StoredOverlayTrace): void {
190	  try {
191	    const sealed = buildSealedOverlayTraceChunks(trace, appVersion());
192	    const alreadyFlushed = trace.flushedChunks ?? 0;
193	    const chunks = sealed.slice(alreadyFlushed);
194	    if (chunks.length === 0) return;
195	    trace.flushedChunks = sealed.length;
196	    persistTrace(trace);
197	    void invoke("queue_recording_chunks", { chunks, result: null }).catch(() => {
198	      // Leave them for the next flush or the end-of-episode submit.
199	      trace.flushedChunks = alreadyFlushed;
200	    });
201	  } catch {
202	    // Recording must never interrupt gameplay.
203	  }
204	}
