function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
}

function gameTitle(gameId: string): string {
  return MENU_GAMES.find((item) => item.id === gameId)?.title ?? gameId;
