500	 * What the shared model account is doing to this shift, and the timer that
501	 * takes the banner down if the transport goes quiet. A throttle gets no
502	 * follow-up report -- the next request simply happens later -- so the
503	 * countdown is what clears it.
504	 */
505	let workerBudget: WorkerBudgetState = WORKER_BUDGET_CLEAR;
506	let workerBudgetTimer: ReturnType<typeof setTimeout> | undefined;
507	
508	function setWorkerBudget(state: WorkerBudgetState): void {
509	  workerBudget = state;
510	  if (workerBudgetTimer !== undefined) clearTimeout(workerBudgetTimer);
511	  workerBudgetTimer = undefined;
512	  const message = workerBudgetMessage(state, workerModelLabel());
513	  if (!message) {
514	    setWorkerMode();
515	    return;
516	  }
517	  setWorkerMode(message, "waiting");
518	  workerBudgetTimer = setTimeout(() => setWorkerBudget(WORKER_BUDGET_CLEAR), workerBudgetHoldMs(state));
519	}
520	
521	function setWorkerMode(message = workerModelLabel(), tone: "live" | "pending" | "waiting" | "error" | undefined = workerModel ? "live" : undefined): void {
522	  const status = screenElement.querySelector<HTMLElement>("[data-arena-worker-mode]");
523	  if (!status) return;
524	  status.textContent = message;
525	  if (tone) status.dataset.tone = tone;
526	  else delete status.dataset.tone;
527	}
528	
529	function setWorkerStatus(role: Role | "expediter", status: "idle" | "thinking" | "acting" | "error"): void {
530	  restaurantArenaScene?.setWorkerStatus(role, status);
531	}
532	
533	function addWorkerActivity(message: string): void {
534	  workerActivity.unshift(message);
535	  workerActivity.splice(8);
536	  const feed = screenElement.querySelector<HTMLOListElement>("[data-arena-worker-activity]");
537	  if (!feed) return;
538	  feed.replaceChildren(...workerActivity.map((entry) => {
539	    const item = document.createElement("li");
540	    item.textContent = entry;
541	    return item;
542	  }));
543	}
