545	function stopWorkerOrchestrator(): void {
546	  workerOrchestrator?.stop();
547	  workerOrchestrator = undefined;
548	  // Leaving the shift ends the wait it described; a banner counting down over
549	  // the menu would be describing requests nobody is making.
550	  if (workerBudgetTimer !== undefined) clearTimeout(workerBudgetTimer);
551	  workerBudgetTimer = undefined;
552	  workerBudget = WORKER_BUDGET_CLEAR;
553	}
