666	/** Wire the static shell once per mount; content refreshes in place after. */
667	function bindInterventionPanel(): void {
668	  const els = interveneEls();
669	  if (!els.toggle || !els.panel) return;
670	  interveneRole = "chef";
671	
672	  els.toggle.addEventListener("click", () => {
673	    const opening = els.panel!.hidden;
674	    els.panel!.hidden = !opening;
675	    els.toggle!.setAttribute("aria-expanded", String(opening));
676	    if (opening && game) refreshInterventionPanel(game);
677	  });
678	  els.close?.addEventListener("click", () => {
679	    els.panel!.hidden = true;
680	    els.toggle!.setAttribute("aria-expanded", "false");
681	  });
682	  els.roles?.addEventListener("click", (event) => {
683	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-role]");
684	    if (!target?.dataset.role) return;
685	    interveneRole = target.dataset.role as PlayerInterventionInput["targetRole"];
686	    els.roles!.querySelectorAll<HTMLButtonElement>("[data-role]").forEach((btn) => btn.classList.toggle("is-selected", btn === target));
687	  });
688	  els.send?.addEventListener("click", () => {
689	    const text = els.text?.value.trim() ?? "";
690	    if (!text) {
691	      setInterveneStatus("Say something first.", "error");
692	      return;
693	    }
694	    submitIntervention({ kind: "message", targetRole: interveneRole, text, priority: els.urgent?.checked ? "high" : "normal" });
695	    if (els.text) els.text.value = "";
696	    if (els.urgent) els.urgent.checked = false;
697	  });
698	  els.correct?.addEventListener("click", () => {
699	    submitIntervention({ kind: "correction", targetRole: interveneRole });
700	  });
701	  // Passing is a decision, so it goes on the record like any other. Doing
702	  // nothing and choosing to do nothing read identically in a trace otherwise.
703	  els.pass?.addEventListener("click", () => {
704	    if (!game) return;
705	    const withPass = game as PlayableGame & { passRound?: () => { accepted: boolean; error?: { message: string } } };
706	    if (!withPass.passRound) return;
707	    workerOrchestrator?.pause();
708	    const result = withPass.passRound();
709	    setInterveneStatus(result.accepted ? "Round passed." : result.error?.message ?? "Could not pass.", result.accepted ? "ok" : "error");
710	    drawGame();
711	  });
712	  els.tickets?.addEventListener("click", (event) => {
713	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-order-id]");
714	    if (!target || target.hasAttribute("data-already-high")) return;
715	    submitIntervention({ kind: "priority", targetRole: interveneRole, orderId: target.dataset.orderId!, priority: "high" });
716	  });
717	  els.approve?.addEventListener("click", (event) => {
718	    const target = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-decision-id]");
719	    if (!target?.dataset.decisionId || !target.dataset.optionId) return;
720	    submitIntervention({
721	      kind: "approve",
722	      targetRole: (target.dataset.speakerRole as PlayerInterventionInput["targetRole"]) ?? interveneRole,
723	      decisionId: target.dataset.decisionId,
724	      optionId: target.dataset.optionId,
725	    });
726	  });
727	}
