/* ── Pause / game-over dialog ─────────────────────────────── */
.return-prompt {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  padding: 28px;
  background: rgba(15, 23, 42, 0.28);
  backdrop-filter: blur(6px);
}
.return-prompt[hidden] { display: none; }
.return-card {
  width: min(100%, 340px);
  padding: 26px 24px 22px;
  border: 1px solid var(--line);
  border-radius: var(--radius-l);
  background: var(--bg-1);
  text-align: center;
  box-shadow: var(--shadow-window);
}
.return-card h2 {
  margin: 0 0 20px;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -.02em;
}
.return-prompt[data-tone="win"] .return-card h2 { color: var(--gold); }
.return-prompt[data-tone="loss"] .return-card h2 { color: var(--danger); }
.return-prompt[data-tone="draw"] .return-card h2 { color: var(--blue); }
.return-actions { display: grid; gap: 8px; }
.return-actions button {
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: var(--radius-m);
  background: var(--bg-3);
  color: var(--ink);
  cursor: pointer;
  font-size: 14px;
  box-shadow: var(--shadow-sm);
  transition: border-color .12s ease, background .12s ease, box-shadow .12s ease;
}
.return-actions button:hover, .return-actions button:focus-visible {
  border-color: var(--hover);
  outline: none;
}
.return-actions .primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
}
.return-actions .primary:hover, .return-actions .primary:focus-visible { background: var(--banana-deep); }
.how-to-play-card {
  width: min(100%, 440px);
  max-height: min(92vh, 640px);
  text-align: left;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.how-to-play-card h2 { text-align: center; }
.how-to-play-body {
  overflow-y: auto;
  display: grid;
  gap: 12px;

