}
.arena-timeline-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.arena-timeline-title {
  font: 800 10px/1.2 var(--mono);
  letter-spacing: .12em;
  color: rgba(255, 255, 255, 0.65);
  text-transform: uppercase;
}
.arena-timeline-badge {
  font: 700 9px/1.2 var(--mono);
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(125, 220, 159, 0.15);
  color: #7ddc9f;
  letter-spacing: .06em;
}
.arena-timeline-milestones {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
