export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

/** A logical (CSS-pixel) frame size, the unit every window API here speaks. */
export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/**
 * The only four frames the overlay ever takes, in logical pixels. The native
 * window boots larger than COMPACT (main.rs clamps a preferred size to the
 * monitor) and the app snaps it to the frame below on load, so these values —
 * not the builder's — are what a player actually sees. `overlay/preview.html`
 * mirrors them so browser work lands on the real box.
 */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/**
 * The floor for a restored frame. It is deliberately larger than
 * {@link PILL_SIZE}: collapsing to the pill has to lower the minimum first,
 * and restoring has to put it back, or the window is stuck at pill size.
 */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

