/**
 * When the shift clock is allowed to run, and which card is over the board.
 *
 * The overlay is a game that sits on top of a coding session, so something
 * else is constantly deciding to interrupt it: the `Stop` hook pauses a run
 * when the agent needs the human back, the human collapses the window to the
 * pill to type, and How to Play / sign-out cards open over whatever is
 * underneath. Every one of those has to hold the clock, and only the last one
 * to open may hand it back.
 *
 * That is a small state machine, and it is the part of the overlay easiest to
 * get subtly wrong (a shift that keeps cooking behind a modal, a card that
 * resumes a run the player never un-paused). So it lives here as pure
 * transitions over an immutable value, and app.ts only renders the result.
 */

/** The card currently over the board; "none" when the board is clear. */
export type OverlayDialog = "none" | "paused" | "how-to-play" | "signout";

export interface PauseState {
  /**
   * The run is held: the agent asked for the human back, or the human opened
   * the pause card. Independent of `dialog`, which the pill hides without
   * un-holding anything.
   */
  readonly paused: boolean;
  readonly dialog: OverlayDialog;
  /** Collapsed to the draggable pill; the whole app is off screen. */
  readonly minimized: boolean;
}

export const INITIAL_PAUSE_STATE: PauseState = {
  paused: false,
  dialog: "none",
  minimized: false,
};

/**
 * The host asked for the human back (`gamepigeon:pause`, the `Stop` hook).
 * With no run on screen there is nothing to hold and nothing to say, so the
 * menu is left alone rather than sprouting a "Paused" card over it.
 */
export function pauseForAgent(state: PauseState, runLive: boolean): PauseState {
  if (!runLive) return state;
  return { ...state, paused: true, dialog: "paused" };
}

/** Back to playing: the hold is released and the pause card goes away. */
export function resumePlay(state: PauseState): PauseState {
  return { ...state, paused: false, dialog: state.dialog === "paused" ? "none" : state.dialog };
}

export function openDialog(state: PauseState, dialog: Exclude<OverlayDialog, "none">): PauseState {
  return { ...state, dialog };
}

/**
 * Dismiss the top card. A run that was paused before the card opened stays
 * paused — closing How to Play mid-shift must not start the clock behind the
 * pause card it was opened from.
 */
export function closeDialog(state: PauseState): PauseState {
  return { ...state, dialog: state.paused ? "paused" : "none" };
}

/**
 * Collapse to the pill. Cards are left exactly as they were: the pill hides
 * them (CSS), and coming back should show what the player left open.
 */
export function minimize(state: PauseState): PauseState {
  return { ...state, minimized: true };
}

export function restore(state: PauseState): PauseState {
  return { ...state, minimized: false };
}

/**
 * What `Esc` means right now.
 *
 * "minimize" is the fallback because the pause card labels its own primary
 * button `Esc — Back to coding`, and going back to coding is exactly the
 * minimize-to-pill gesture: the run stays held, the terminal is usable again.
 */
export function escapeAction(state: PauseState): "close" | "minimize" | "none" {
  if (state.minimized) return "none";
  if (state.dialog === "how-to-play" || state.dialog === "signout") return "close";
  return "minimize";
}

/**
 * Whether the shift clock (the tick timer or the worker orchestrator) may
 * advance. Anything over the board or a collapsed window holds it, so a run
 * never cooks on behind something the player is reading.
 */
export function clockRunning(state: PauseState, runLive: boolean): boolean {
  return runLive && !state.paused && !state.minimized && state.dialog === "none";
}

