/**
 * Opens the record for a brand-new run. `ownerId` is the signed-in account, so
 * a launch under a different account never resumes someone else's shift; the
 * browser preview has no account and uses "".
 */
export function startSavedGame(
  entry: GameEntry,
  variationId: string,
  seed: number,
  ownerId: string,
): SavedGame {
  return {
    schemaVersion: 1,
    ownerId,
    gameId: entry.id,
    gameVersion: entry.version,
    variationId,
    seed,
    actions: [],
  };
}

/**
 * Records one accepted action on the run. Returns false once the log is full,
 * which is the point the save stops describing the run — the caller drops it
 * rather than keeping a record that would replay to the wrong state.
 */
export function appendSavedAction(saved: SavedGame, action: string): boolean {
  if (saved.actions.length >= MAX_ACTIONS) return false;
  saved.actions.push(action);
  return true;
}

export function writeSavedGame(saved: SavedGame, storage: Storage = localStorage): void {
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // A full or blocked store costs the resume, never the run in progress.
  }
}

export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Same: losing the ability to forget a run must not interrupt gameplay.
  }
}

/**
 * A seed for a brand-new run. `previous` is the seed being replaced: restart
 * means "start over with a new run", so it is explicitly excluded — replaying
 * the same seed is what a resume does, not what a restart does.
 */
export function randomSeed(previous?: number, random: () => number = Math.random): number {
  for (let attempt = 0; attempt < 8; attempt++) {
    const seed = Math.floor(random() * 2_147_483_647);
    if (seed !== previous) return seed;
  }
  // Vanishingly unlikely (or a stubbed generator): step off the collision
  // rather than hand back the seed we were told not to reuse.
  return ((previous ?? 0) + 1) % 2_147_483_647;
}

