score(): number {
    const out = this.currentState.outcomes;
    return Math.round(
      out.cash +
      out.safeOrders * 50 +
      out.satisfaction * 100 -
      out.waste * 10
    );
  }

  isOver(): boolean {
    return this.currentState.episode.phase === "complete";
  }

  hasWon(): boolean {
    return this.isOver() && this.currentState.outcomes.safeOrders > 0;
  }

  checkpointState(): unknown {
    return {
      state: this.state(),
