function drawGame(): void {
  if (!game || !entry) return;
  const patch = screenElement.dataset.game === "restaurant-arena" ? updateRestaurantArena : undefined;
  if (!patch?.(game)) {
    renderGameScreen();
    return;
  }
  setPersonalBest();
}

tool_use_result.newString:
function drawGame(): void {
  if (!game || !entry) return;
  const patch = screenElement.dataset.game === "restaurant-arena" ? updateRestaurantArena : undefined;
  if (patch?.(game)) setPersonalBest();
  else renderGameScreen();
  // A shift can end on any path that draws — a player action, a worker tick, a
  // replayed step — so the debrief is raised here instead of at each caller.
  if (game.isOver() && !gameEnded) finishRun();
  // Whatever just happened may have started or stopped the clock (`sim_toggle`,
  // an incident opening a decision card, the shift ending); every caller
  // relies on this to re-enter the scheduler it paused.
  syncClock();
}

// ── Window frame ──────────────────────────────────────────────────────
//
// The native window boots bigger than the compact frame (main.rs clamps a
// preferred size against the monitor), so the sizes in tauri-bridge.ts are
// applied on load and after every toggle. Order matters in both directions:
// the minimum is set before the size, because the pill is smaller than the
// restored floor and a stale minimum would silently clamp it.

function frameSize(): OverlaySize {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

async function applySize(size: OverlaySize, minimum: OverlaySize): Promise<void> {
  try {
    await windowHandle.setMinSize(overlayLogicalSize(minimum.width, minimum.height));
    await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  } catch {
    // A window that refuses to resize is not a reason to lose the run.
  }
}

/** Reflect the current frame on the titlebar toggle. */
function renderResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  button.textContent = expanded ? "↙" : "↗";
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

function applyFrame(): Promise<void> {
  renderResizeButton();
  return applySize(frameSize(), MIN_SIZE);
}

function toggleFrame(): void {
  expanded = !expanded;
  void applyFrame();
}

/**
 * Collapse to the handheld pill. The run is left exactly as it is — held by
 * `clockRunning`, not ended — because this is the "back to coding" gesture and
 * the player expects to find their shift where they left it.
 */
function minimizeToPill(): void {
  if (pauseState.minimized) return;
  pauseState = minimize(pauseState);
  document.body.dataset.mode = "pill";
  syncDialogs();
  syncClock();
  void applySize(PILL_SIZE, PILL_SIZE).then(() => {
    document.querySelector<HTMLButtonElement>("#pill")?.focus();
  });
}

function restoreFromPill(): void {
  if (!pauseState.minimized) return;
  pauseState = restore(pauseState);
  delete document.body.dataset.mode;
  syncDialogs();
  syncClock();
  void applyFrame().then(() => windowHandle.center()).catch(() => undefined);
}

function bindWindowChrome(): void {
  document.querySelector<HTMLButtonElement>("#resize")?.addEventListener("click", toggleFrame);
  document.querySelector<HTMLButtonElement>("#hide")?.addEventListener("click", minimizeToPill);
  document.querySelector<HTMLButtonElement>("#shutdown")?.addEventListener("click", () => {
    // Rust writes the session's shutdown flag and exits, so the launcher stops
    // re-opening the overlay until the next session. A no-op in the browser.
    void invoke("shutdown").catch(() => undefined);
  });

  const pill = document.querySelector<HTMLButtonElement>("#pill");
  if (!pill) return;
  // The pill is both the drag handle and the reopen button, so dragging is
  // armed on movement rather than on press: `startDragging` hands the pointer
  // to the compositor, and the click that would reopen the window never
  // arrives after it.
  let pressedAt: { x: number; y: number } | undefined;
  let dragged = false;
  pill.addEventListener("pointerdown", (event) => {
    pressedAt = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  pill.addEventListener("pointermove", (event) => {
    if (!pressedAt || dragged) return;
    if (Math.abs(event.clientX - pressedAt.x) + Math.abs(event.clientY - pressedAt.y) < 4) return;
    dragged = true;
    void windowHandle.startDragging().catch(() => undefined);
  });
  pill.addEventListener("pointerup", () => { pressedAt = undefined; });
  pill.addEventListener("click", () => {
    if (dragged) {
      dragged = false;
      return;
    }
    restoreFromPill();
  });
}

// ── Cards over the board ──────────────────────────────────────────────
//
// Three of them (paused, How to Play, sign-out) live in index.html rather than
// in `#screen`, so they survive a screen repaint. pause-state.ts decides which
// one is up; this only renders that decision and moves focus.

function syncDialogs(): void {
  const cards: [string, PauseState["dialog"]][] = [
    ["#return-prompt", "paused"],
    ["#how-to-play", "how-to-play"],
    ["#signout-prompt", "signout"],
  ];
  for (const [selector, dialog] of cards) {
    const card = document.querySelector<HTMLElement>(selector);
    if (card) card.hidden = pauseState.dialog !== dialog;
  }
}

function focusDialog(selector: string): void {
  document.querySelector<HTMLElement>(selector)?.focus();
}

function showDialog(dialog: "paused" | "how-to-play" | "signout"): void {
  pauseState = openDialog(pauseState, dialog);
  syncDialogs();
  syncClock();
  if (dialog === "how-to-play") focusDialog("#how-to-play-close");
  else if (dialog === "signout") focusDialog("#signout-cancel");
  else focusDialog("#continue-game");
}

function closeTopDialog(): void {
  pauseState = closeDialog(pauseState);
  syncDialogs();
  syncClock();
}

/** Continue playing: releases the hold and takes the pause card down. */
function continuePlaying(): void {
  pauseState = resumePlay(pauseState);
  syncDialogs();
  syncClock();
}

function confirmSignOut(): void {
  void signOut().then(() => {
    // Leaving the shift keeps its save exactly as it is; the next launch only
    // offers it back to the account that owns it.
    endShift("user_quit");
    pauseState = INITIAL_PAUSE_STATE;
    syncDialogs();
    savedGame = undefined;
    drawGate();
  }).catch(() => {
    // signOut() throws with credentials still on disk, so the session is
    // genuinely still open — say nothing and leave the confirmation up.
    focusDialog("#signout-cancel");
  });
}

function bindDialogs(): void {
  const on = (selector: string, handler: () => void) =>
    document.querySelector<HTMLButtonElement>(selector)?.addEventListener("click", handler);
  // "Back to coding" is the minimize gesture: the terminal is usable again and
  // the run stays held until the next `gamepigeon:resume`.
  on("#return-code", minimizeToPill);
  on("#continue-game", continuePlaying);
  on("#how-to-play-from-pause", () => showDialog("how-to-play"));
  on("#return-menu", () => endShift("user_quit"));
  on("#how-to-play-close", closeTopDialog);
  on("#signout-cancel", closeTopDialog);
  on("#signout-confirm", confirmSignOut);
  syncDialogs();
}

// ── Session lifecycle ─────────────────────────────────────────────────

function activeVariationId(): string {
  return entry?.variations[variationCursor]?.id ?? "classic";
}

/** A run is on screen and still playable — not a debrief, not the menu. */
function runLive(): boolean {
  return game !== undefined && !gameEnded && !game.isOver();
}

function stopTicker(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

/**
 * Arms the deterministic shift clock. `tickMs()` is the engine's own answer to
 * "may time pass right now" — it returns 0 for a shift that has not started,
 * one holding on a decision card, and one that is over.
 */
function scheduleTick(): void {
  if (tickTimer !== undefined) return;
  const interval = game?.tickMs?.() ?? 0;
  if (interval <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (!game || !clockRunning(pauseState, runLive()) || (game.tickMs?.() ?? 0) <= 0) return;
    // Authored by the environment, not the player: this is the clock.
    stepGame("tick", "environment");
    actionsTaken++;
    drawGame();
  }, interval);
}

/** Exactly one scheduler runs a shift, and only while nothing is over it. */
function syncClock(): void {
  if (!clockRunning(pauseState, runLive())) {
    stopTicker();
    workerOrchestrator?.pause();
    return;
  }
  if (workerOrchestrator) {
    stopTicker();
    // start() resumes an already-running loop instead of double-pumping it.
    workerOrchestrator.start();
    return;
  }
  scheduleTick();
}

/** Whoever owns the current save: the signed-in account, or "" in the browser. */
function saveOwnerId(): string {
  return signedInUser()?.id ?? "";
}

/** The same split `performAction` records, so a replay reproduces its authors. */
function actionActor(action: string): TraceActor {
  return action === "tick" || action === "bot_move" ? "environment" : "human";
}

function leaveGameScreen(): void {
  stopTicker();
  stopWorkerOrchestrator();
  cancelTraceFlush();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  gameEnded = false;
  replaying = false;
}

/**
 * Opens a run: a fresh one, or a stored one rebuilt action-by-action.
 *
 * The save is written here rather than at the first action, so a launch that
 * crashes before the player touches anything still resumes the same seed.
 */
function startRun(selected: GameEntry, variationId: string, restored?: { game: PlayableGame; actions: string[]; seed: number }): void {
  if (!selected.create) return;
  leaveGameScreen();
  entry = selected;
  cursor = Math.max(0, MENU_GAMES.findIndex(({ id }) => id === selected.id));
  variationCursor = Math.max(0, selected.variations.findIndex(({ id }) => id === variationId));
  const resolvedVariation = selected.variations[variationCursor]?.id ?? variationId;

  const seed = restored?.seed ?? randomSeed();
  game = restored?.game ?? selected.create(resolvedVariation);
  if (!restored) game.reset(seed);

  const replayedActions = restored?.actions ?? [];
  gameStartedAt = Date.now();
  actionsTaken = replayedActions.length;
  gameEnded = false;

  activeTrace = createOverlayTrace(selected, resolvedVariation, seed);
  for (const action of replayedActions) appendOverlayAction(activeTrace, action, actionActor(action));
  persistTrace(activeTrace);
  // One id names the run everywhere it can be matched back: the trace export,
  // the queued chunks, the completed-game result, the analytics subject, and
  // the receipt printed on the debrief (#281).
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = activeTrace.gameId;

  savedGame = startSavedGame(selected, resolvedVariation, seed, saveOwnerId());
  // Only the actions the engine still accepts survive a rebuild, so the save is
  // rewritten from what actually replayed rather than from what was stored.
  for (const action of replayedActions) appendSavedAction(savedGame, action);
  writeSavedGame(savedGame);

  screen = "game";
  pauseState = { ...resumePlay(pauseState), dialog: "none" };
  syncDialogs();
  attachWorkerOrchestrator(game);
  renderGameScreen();
  captureOverlayEvent(
    "game.started",
    { game_type: selected.id, variation_id: resolvedVariation },
    gameSessionId,
  );
  syncClock();
}

/** Rebuild the stored run, or drop a save this build can no longer replay. */
function resumeSavedGame(): void {
  const saved = savedGame;
  const found = saved ? MENU_GAMES.find(({ id }) => id === saved.gameId) : undefined;
  const restored = saved && found ? restoreGame(found, saved) : null;
  if (!saved || !found || !restored) {
    clearSavedGame();
    savedGame = undefined;
    screen = "menu";
    drawMenu();
    return;
  }
  startRun(found, saved.variationId, { ...restored, seed: saved.seed });
}

/**
 * Hands the run's trace to the recording store and logs the outcome. Runs
 * before the debrief is built, which is why the receipt id is kept separately.
 */
function endGame(reason: EpisodeEndReason, completedScore?: number): void {
  stopTicker();
  stopWorkerOrchestrator();
  cancelTraceFlush();
  const finishedGame = game;
  const finishedEntry = entry;
  if (finishedGame && reason !== "won" && reason !== "lost") {
    const withAbandon = finishedGame as PlayableGame & { markAbandoned?: (reason: string) => void };
    withAbandon.markAbandoned?.(reason);
  }
  if (activeTrace) {
    submitTrace(activeTrace, reason, completedScore);
    activeTrace = undefined;
  }
  if (!finishedGame || !finishedEntry) return;
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const completed = completedScore !== undefined;
  captureOverlayEvent("game.ended", {
    game_type: finishedEntry.id,
    variation_id: activeVariationId(),
    outcome: completed ? "completed" : "abandoned",
    score: finishedGame.score(),
    success: finishedGame.hasWon(),
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, gameSessionId);
  if (!completed || !gameSessionId) return;
  void invoke("append_local_score", {
    score: {
      game_id: gameSessionId,
      game_type: finishedEntry.id,
      variation_id: activeVariationId(),
      // The local log holds completed-run scores, which cannot be negative; a
      // shift that burned more than it took home lands at zero rather than
      // being rejected and lost.
      score: Math.max(0, Math.round(completedScore)),
      success: finishedGame.hasWon(),
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
}

/** The shift ran to the end of the night: score it and show the debrief. */
function finishRun(): void {
  if (!game || gameEnded) return;
  gameEnded = true;
  const score = game.score();
  const won = game.hasWon();
  // Nothing left to resume, and the debrief is the last word on this run.
  clearSavedGame();
  savedGame = undefined;
  endGame(won ? "won" : "lost", score);
  renderEndCard();
}

/**
 * Ending a shift mid-run: back to the menu with the save untouched, so the
 * same seed and action log can be resumed on a later launch (README §Session
 * save). The window is deliberately not touched — a host `gamepigeon:reset`
 * snaps a hidden overlay back to the menu without popping it open.
 */
function endShift(reason: EpisodeEndReason = "user_quit"): void {
  if (game && !gameEnded) endGame(reason);
  leaveGameScreen();
  pauseState = { ...resumePlay(pauseState), dialog: "none" };
  syncDialogs();
  screen = "menu";
  cursor = -1;
  drawMenu();
}

/**
 * Restart mid-run: a brand-new run of the same game and variation. The stored
 * run is thrown away and the seed is re-randomized — restart means "start
 * over", so only a resume replays a stored seed (README §Session save).
 */
function restartRun(): void {
  const selected = entry;
  if (!selected) return;
  const variationId = activeVariationId();
  const previousSeed = savedGame?.seed;
  if (game && !gameEnded) endGame("restart");
  clearSavedGame();
  savedGame = undefined;
  const withSeed = { seed: randomSeed(previousSeed) };
  const fresh = selected.create?.(variationId);
  if (!fresh) return;
  fresh.reset(withSeed.seed);
  startRun(selected, variationId, { game: fresh, actions: [], seed: withSeed.seed });
}

// ── Debrief card ──────────────────────────────────────────────────────

/** Won / lost / neither, for the card's accent colour. */
function endTone(): "win" | "loss" | "draw" {
  if (!game) return "draw";
  return game.hasWon() ? "win" : "loss";
}

function endCardActionsHtml(): string {
  const exportGroup = game?.name === "restaurant-arena"
    ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
      </div>`
    : "";
  return `<div class="game-end-actions">
    <button type="button" class="primary" data-end="restart"><kbd>Enter</kbd> Play again</button>
    ${exportGroup}
    <button type="button" data-end="menu"><kbd>M</kbd> Menu</button>
  </div>`;
}

/**
 * The debrief, over the board the shift was played on. Rebuilt rather than
 * patched, and always removed first, so a repaint can re-raise it without
 * stacking two cards.
 */
function renderEndCard(): void {
  if (!game || !entry) return;
  screenElement.querySelector(".game-end-overlay")?.remove();
  const board = screenElement.querySelector<HTMLElement>(".board") ?? screenElement;
  const isArena = game.name === "restaurant-arena";
  const score = game.score();
  const best = personalBest(entry.id, score);
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = endTone();
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${game.hasWon() ? "Shift complete" : "Shift over"}</h2>
    <p class="game-end-stats">Score ${score}${best === undefined ? "" : ` · Personal best ${best}`}</p>
    ${getArenaDebriefHtml()}
    ${getArenaTimelineHtml()}
    ${getArenaEvidenceHtml()}
    ${sessionReceiptHtml()}
    ${endCardActionsHtml()}
  </div>`;
  board.appendChild(overlay);
  overlay.querySelector<HTMLButtonElement>('[data-end="restart"]')?.focus();
}

