88	function browserKey(event: KeyboardEvent): Key | null {
89	  switch (event.key) {
90	    case "ArrowUp": return "up";
91	    case "ArrowDown": return "down";
92	    case "ArrowLeft": return "left";
93	    case "ArrowRight": return "right";
94	    case "Enter": return "enter";
95	    case "Backspace": return "backspace";
96	  }
97	  if (event.key.length !== 1) return null;
98	  const lower = event.key.toLowerCase();
99	  if (lower === "w") return "up";
100	  if (lower === "s") return "down";
101	  if (lower === "a") return "left";
102	  if (lower === "d") return "right";
103	  if (lower === "q") return "quit";
104	  return { char: event.key };
