204	/**
205	 * Hands full chunks to the local recording store while the episode is still
206	 * running, so a long game is not stuck in the browser journal until it ends.
207	 * Sealed chunks are byte-stable, so the store treats the eventual final
208	 * submit of the same chunk ids as a no-op.
209	 */
210	const FLUSH_INTERVAL_MS = 5_000;
211	let flushTimer: number | undefined;
