213	/**
214	 * Sealing replays the whole journal, so coalesce bursts of input (a gravity
215	 * tick arrives several times a second) onto a slow timer.
216	 */
217	function scheduleTraceFlush(trace: StoredOverlayTrace): void {
218	  if (flushTimer !== undefined) return;
219	  flushTimer = window.setTimeout(() => {
220	    flushTimer = undefined;
221	    if (activeTrace === trace) flushSealedTrace(trace);
222	  }, FLUSH_INTERVAL_MS);
223	}
