230	function flushSealedTrace(trace: StoredOverlayTrace): void {
231	  try {
232	    const sealed = buildSealedOverlayTraceChunks(trace, appVersion());
233	    const alreadyFlushed = trace.flushedChunks ?? 0;
234	    const chunks = sealed.slice(alreadyFlushed);
235	    if (chunks.length === 0) return;
236	    trace.flushedChunks = sealed.length;
237	    persistTrace(trace);
238	    void invoke("queue_recording_chunks", { chunks, result: null }).catch(() => {
239	      // Leave them for the next flush or the end-of-episode submit.
240	      trace.flushedChunks = alreadyFlushed;
241	    });
242	  } catch {
243	    // Recording must never interrupt gameplay.
244	  }
245	}
