247	function submitTrace(
248	  trace: StoredOverlayTrace,
249	  reason: EpisodeEndReason,
250	  completedScore?: number,
251	): void {
252	  if (!settings.recordingWhilePlaying) return;
253	  try {
254	    trace.endReason ??= reason;
255	    trace.endedAtMs ??= Date.now();
256	    trace.completedScore ??= completedScore;
257	    persistTrace(trace);
258	    const chunks = buildOverlayTraceChunks(
259	      trace,
260	      trace.endReason,
261	      appVersion(),
262	      trace.endedAtMs,
263	    );
264	    void invoke("queue_recording_chunks", {
265	      chunks,
266	      result: buildOverlayGameResult(trace),
267	    }).then(() => {
268	      localStorage.removeItem(`${TRACE_KEY_PREFIX}${trace.gameId}`);
269	    }).catch(() => {
270	      // Keep the compact seed/action journal for the next launch.
271	    });
272	  } catch {
273	    // Keep the journal if replay or serialization fails.
274	  }
275	}
