277	function recoverTraces(): void {
278	  const pending: StoredOverlayTrace[] = [];
279	  for (let index = 0; index < localStorage.length; index++) {
280	    const key = localStorage.key(index);
281	    if (!key?.startsWith(TRACE_KEY_PREFIX)) continue;
282	    try {
283	      pending.push(JSON.parse(localStorage.getItem(key)!) as StoredOverlayTrace);
284	    } catch {
285	      // Preserve malformed recovery data for manual inspection.
286	    }
287	  }
288	  for (const trace of pending) submitTrace(trace, trace.endReason ?? "client_closed");
