}

// ── Cards over the board ──────────────────────────────────────────────
//
// Three of them (paused, How to Play, sign-out) live in index.html rather than
// in `#screen`, so they survive a screen repaint. pause-state.ts decides which
// one is up; this only renders that decision and moves focus.

function syncDialogs(): void {
  const cards: [string, PauseState["dialog"]][] = [
    ["#return-prompt", "paused"],
    ["#how-to-play", "how-to-play"],
    ["#signout-prompt", "signout"],
  ];
  for (const [selector, dialog] of cards) {
    const card = document.querySelector<HTMLElement>(selector);
    if (card) card.hidden = pauseState.dialog !== dialog;
  }
}

function focusDialog(selector: string): void {
  document.querySelector<HTMLElement>(selector)?.focus();
}

function showDialog(dialog: "paused" | "how-to-play" | "signout"): void {
  pauseState = openDialog(pauseState, dialog);
  syncDialogs();
  syncClock();
  if (dialog === "how-to-play") focusDialog("#how-to-play-close");
  else if (dialog === "signout") focusDialog("#signout-cancel");
  else focusDialog("#continue-game");
}

function closeTopDialog(): void {
  pauseState = closeDialog(pauseState);
  syncDialogs();
  syncClock();
}

/** Continue playing: releases the hold and takes the pause card down. */
function continuePlaying(): void {
  pauseState = resumePlay(pauseState);
  syncDialogs();
  syncClock();
}

function confirmSignOut(): void {
  void signOut().then(() => {
    // Leaving the shift keeps its save exactly as it is; the next launch only
    // offers it back to the account that owns it.
    endShift("user_quit");
    pauseState = INITIAL_PAUSE_STATE;
    syncDialogs();
    savedGame = undefined;
    drawGate();
  }).catch(() => {
    // signOut() throws with credentials still on disk, so the session is
    // genuinely still open — say nothing and leave the confirmation up.
    focusDialog("#signout-cancel");
  });
}

function bindDialogs(): void {
  const on = (selector: string, handler: () => void) =>
    document.querySelector<HTMLButtonElement>(selector)?.addEventListener("click", handler);
  // "Back to coding" is the minimize gesture: the terminal is usable again and
  // the run stays held until the next `gamepigeon:resume`.
  on("#return-code", minimizeToPill);
  on("#continue-game", continuePlaying);
  on("#how-to-play-from-pause", () => showDialog("how-to-play"));
  on("#return-menu", () => endShift("user_quit"));
  on("#how-to-play-close", closeTopDialog);
  on("#signout-cancel", closeTopDialog);
  on("#signout-confirm", confirmSignOut);
