arguments.new_string:
/** Whoever owns the current save: the signed-in account, or "" in the browser. */
function saveOwnerId(): string {
  return signedInUser()?.id ?? "";
}

// The resume record grows by one entry per accepted action, and a busy shift
// accepts several a second, so the JSON is written on a slow timer instead of
// on every step. Losing the last couple of seconds of a run to a hard kill
// costs the player nothing they will notice; re-serializing a long action log
// at tick rate would.
const SAVE_INTERVAL_MS = 2_000;
let saveTimer: number | undefined;
let savePending = false;

function flushSavedGame(): void {
  if (saveTimer !== undefined) window.clearTimeout(saveTimer);
  saveTimer = undefined;
  if (savePending && savedGame) writeSavedGame(savedGame);
  savePending = false;
}

function scheduleSavedGameWrite(): void {
  savePending = true;
  if (saveTimer === undefined) saveTimer = window.setTimeout(flushSavedGame, SAVE_INTERVAL_MS);
}

/** Forget the run in progress entirely: nothing to resume, nothing to write. */
function dropSavedGame(): void {
  savePending = false;
  if (saveTimer !== undefined) window.clearTimeout(saveTimer);
  saveTimer = undefined;
  savedGame = undefined;
  clearSavedGame();
}

/** Record one accepted action on the resume record. */
function recordSavedAction(action: string): void {
  const saved = savedGame;
  if (!saved) return;
  if (!appendSavedAction(saved, action)) {
    // Past the log's ceiling the record no longer describes the run, and
    // replaying a truncated log would rebuild the wrong shift — so it is
    // dropped rather than offered back as a resume.
    dropSavedGame();
    return;
  }
  scheduleSavedGameWrite();
}

