/**
 * Opens a run: a fresh one, or a stored one rebuilt action-by-action.
 *
 * The save is written here rather than at the first action, so a launch that
 * crashes before the player touches anything still resumes the same seed.
 */
function startRun(selected: GameEntry, variationId: string, restored?: { game: PlayableGame; actions: string[]; seed: number }): void {
  if (!selected.create) return;
  leaveGameScreen();
  entry = selected;
  cursor = Math.max(0, MENU_GAMES.findIndex(({ id }) => id === selected.id));
  variationCursor = Math.max(0, selected.variations.findIndex(({ id }) => id === variationId));
  const resolvedVariation = selected.variations[variationCursor]?.id ?? variationId;

  const seed = restored?.seed ?? randomSeed();
  game = restored?.game ?? selected.create(resolvedVariation);
  if (!restored) game.reset(seed);

  const replayedActions = restored?.actions ?? [];
  gameStartedAt = Date.now();
  actionsTaken = replayedActions.length;
  gameEnded = false;

  activeTrace = createOverlayTrace(selected, resolvedVariation, seed);
  for (const action of replayedActions) appendOverlayAction(activeTrace, action, actionActor(action));
  persistTrace(activeTrace);
  // One id names the run everywhere it can be matched back: the trace export,
  // the queued chunks, the completed-game result, the analytics subject, and
  // the receipt printed on the debrief (#281).
  gameSessionId = activeTrace.gameId;
  sessionReceiptId = activeTrace.gameId;

  savedGame = startSavedGame(selected, resolvedVariation, seed, saveOwnerId());
  // Only the actions the engine still accepts survive a rebuild, so the save is
  // rewritten from what actually replayed rather than from what was stored.
  for (const action of replayedActions) appendSavedAction(savedGame, action);
  writeSavedGame(savedGame);

  screen = "game";
  pauseState = { ...resumePlay(pauseState), dialog: "none" };
  syncDialogs();
  attachWorkerOrchestrator(game);
  renderGameScreen();
  captureOverlayEvent(
    "game.started",
    { game_type: selected.id, variation_id: resolvedVariation },
    gameSessionId,
  );
  syncClock();
}

/** Rebuild the stored run, or drop a save this build can no longer replay. */
function resumeSavedGame(): void {
  const saved = savedGame;
  const found = saved ? MENU_GAMES.find(({ id }) => id === saved.gameId) : undefined;
  const restored = saved && found ? restoreGame(found, saved) : null;
  if (!saved || !found || !restored) {
    clearSavedGame();
    savedGame = undefined;
    screen = "menu";
    drawMenu();
    return;
  }
  startRun(found, saved.variationId, { ...restored, seed: saved.seed });
}

/**
 * Hands the run's trace to the recording store and logs the outcome. Runs
 * before the debrief is built, which is why the receipt id is kept separately.
 */
function endGame(reason: EpisodeEndReason, completedScore?: number): void {
  stopTicker();
  stopWorkerOrchestrator();
  cancelTraceFlush();
  const finishedGame = game;
  const finishedEntry = entry;
  if (finishedGame && reason !== "won" && reason !== "lost") {
    const withAbandon = finishedGame as PlayableGame & { markAbandoned?: (reason: string) => void };
    withAbandon.markAbandoned?.(reason);
  }
  if (activeTrace) {
    submitTrace(activeTrace, reason, completedScore);
    activeTrace = undefined;
  }
  if (!finishedGame || !finishedEntry) return;
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const completed = completedScore !== undefined;
  captureOverlayEvent("game.ended", {
    game_type: finishedEntry.id,
    variation_id: activeVariationId(),
    outcome: completed ? "completed" : "abandoned",
    score: finishedGame.score(),
    success: finishedGame.hasWon(),
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, gameSessionId);
  if (!completed || !gameSessionId) return;
  void invoke("append_local_score", {
    score: {
      game_id: gameSessionId,
      game_type: finishedEntry.id,
      variation_id: activeVariationId(),
      // The local log holds completed-run scores, which cannot be negative; a
      // shift that burned more than it took home lands at zero rather than
      // being rejected and lost.
      score: Math.max(0, Math.round(completedScore)),
      success: finishedGame.hasWon(),
      completed_at: new Date().toISOString(),
      duration_ms: durationMs,
      platform: "overlay",
    },
  }).then(() => refreshLocalScores()).catch(() => undefined);
}

/** The shift ran to the end of the night: score it and show the debrief. */
function finishRun(): void {
  if (!game || gameEnded) return;
  gameEnded = true;
  const score = game.score();
  const won = game.hasWon();
  // Nothing left to resume, and the debrief is the last word on this run.
  clearSavedGame();
  savedGame = undefined;
  endGame(won ? "won" : "lost", score);
  renderEndCard();
}

