  else if (typeof key === "object" && key.char === "?") showDialog("how-to-play");
}

/** The debrief is modal over a finished board: only its own actions apply. */
function handleEndCardKey(key: Key): void {
  if (key === "enter") restartRun();
  else if (key === "quit") endShift("user_quit");
  else if (typeof key === "object" && key.char.toLowerCase() === "m") endShift("user_quit");
}

/**
 * Keys while a card is up. The pause card's own labels are the contract:
 * `Esc` (handled below, as everywhere) and `Enter` both go back to coding,
 * `M` goes to the menu, `Space` keeps playing.
 */
function handlePauseCardKey(key: Key): void {
  if (key === "enter") minimizeToPill();
  else if (typeof key === "object" && (key.char === " " || key.char.toLowerCase() === "c")) continuePlaying();
  else if (typeof key === "object" && key.char.toLowerCase() === "m") endShift("user_quit");
  else if (typeof key === "object" && key.char === "?") showDialog("how-to-play");
}

window.addEventListener("keydown", (event) => {
  const target = event.target as HTMLElement | null;
  if (target?.matches("input, textarea, select, [contenteditable=\"true\"]")) return;
  // Esc means the same thing at every depth, gate included: dismiss the top
  // card, or get out of the way. pause-state.ts decides which.
  if (event.key === "Escape") {
    event.preventDefault();
    const next = escapeAction(pauseState);
    if (next === "close") closeTopDialog();
    else if (next === "minimize") minimizeToPill();
    return;
  }
  // Collapsed: the pill has focus and handles Enter/Space as the button it is,
  // so nothing else may read the keyboard while the app is off screen.
  if (pauseState.minimized) return;
  if (pauseState.dialog !== "none") {
    const dialogKey = browserKey(event);
    if (!dialogKey) return;
    // How to Play and the sign-out confirmation are plain button cards: the
    // focused `.primary` answers Enter/Space itself.
    if (pauseState.dialog !== "paused") return;
    event.preventDefault();
    handlePauseCardKey(dialogKey);
    return;
  }
  if (screen === "gate") {
    // Block menu/game input until signed in; Enter starts sign-in.
    if (event.key === "Enter") { event.preventDefault(); void beginSignIn(); }
    return;
  }
  const key = browserKey(event);
  if (!key) return;
  event.preventDefault();
  if (screen === "menu") handleMenuKey(key);
  else if (screen === "variations") handleVariationKey(key);
  else if (screen === "scores") handleScoresKey(key);
  else if (screen === "settings") handleSettingsKey(key);
  else handleGameKey(key);
});

