 * game's first variation, or — with nothing named — the menu's current
 * selection. An unknown id leaves the player where they are rather than
 * starting a game they did not pick.
 */
function launchFromHost(gameId?: string, variationId?: string): void {
  const selected = gameId
    ? MENU_GAMES.find(({ id }) => id === gameId)
    : entry ?? MENU_GAMES[Math.max(0, cursor)];
  if (!selected || !isPlayable(selected)) return;
  const variation = variationId
    ? selected.variations.find(({ id }) => id === variationId)
    : selected.variations[0];
  if (!variation) return;
  if (pauseState.minimized) restoreFromPill();
  startRun(selected, variation.id);
}

