/**
 * What the arcade opens onto once it is unlocked: a `?game=` deep link — how
 * the browser preview launches a run, having no host to dispatch
 * `gamepigeon:launch` — or the stored shift, when the player asked for it.
 */
function autoStart(): void {
  const params = new URLSearchParams(window.location.search);
  const requested = params.get("game");
  if (requested) {
    launchFromHost(requested, params.get("variation") ?? undefined);
    return;
  }
  if (settings.resumeLastGame && savedGame) resumeSavedGame();
}

