import { describe, expect, test } from "bun:test";
import {
  INITIAL_PAUSE_STATE,
  clockRunning,
  closeDialog,
  escapeAction,
  minimize,
  openDialog,
  pauseForAgent,
  restore,
  resumePlay,
} from "./pause-state.js";

describe("pause state", () => {
  test("the agent asking for the human holds the run and says so", () => {
    const paused = pauseForAgent(INITIAL_PAUSE_STATE, true);
    expect(paused.paused).toBe(true);
    expect(paused.dialog).toBe("paused");
    expect(clockRunning(paused, true)).toBe(false);
  });

  test("nothing to hold on the menu, so no card over it", () => {
    expect(pauseForAgent(INITIAL_PAUSE_STATE, false)).toBe(INITIAL_PAUSE_STATE);
  });

  test("resuming releases the hold and takes the pause card down", () => {
    const resumed = resumePlay(pauseForAgent(INITIAL_PAUSE_STATE, true));
    expect(resumed).toEqual(INITIAL_PAUSE_STATE);
    expect(clockRunning(resumed, true)).toBe(true);
  });

  test("closing How to Play mid-shift does not resume a held run", () => {
    const held = pauseForAgent(INITIAL_PAUSE_STATE, true);
    const reading = openDialog(held, "how-to-play");
    expect(clockRunning(reading, true)).toBe(false);
    const closed = closeDialog(reading);
    // Back to the card it was opened from, still held.
    expect(closed.dialog).toBe("paused");
    expect(closed.paused).toBe(true);
    expect(clockRunning(closed, true)).toBe(false);
  });

  test("closing a card opened while playing hands the shift back", () => {
    const reading = openDialog(INITIAL_PAUSE_STATE, "how-to-play");
    const closed = closeDialog(reading);
    expect(closed.dialog).toBe("none");
    expect(clockRunning(closed, true)).toBe(true);
  });

  test("a card over the board always stops the clock", () => {
    for (const dialog of ["paused", "how-to-play", "signout"] as const) {
      expect(clockRunning(openDialog(INITIAL_PAUSE_STATE, dialog), true)).toBe(false);
    }
  });

  test("the pill holds the run without ending or un-holding anything", () => {
    const collapsed = minimize(INITIAL_PAUSE_STATE);
    expect(clockRunning(collapsed, true)).toBe(false);
    expect(clockRunning(restore(collapsed), true)).toBe(true);

    const heldAndCollapsed = minimize(pauseForAgent(INITIAL_PAUSE_STATE, true));
    // The card the player left open is still open when they come back.
    expect(restore(heldAndCollapsed).dialog).toBe("paused");
    expect(restore(heldAndCollapsed).paused).toBe(true);
  });

  test("no clock without a live run, whatever the cards say", () => {
    expect(clockRunning(INITIAL_PAUSE_STATE, false)).toBe(false);
  });

  test("Esc dismisses the top card, otherwise gets out of the way", () => {
    expect(escapeAction(INITIAL_PAUSE_STATE)).toBe("minimize");
    expect(escapeAction(openDialog(INITIAL_PAUSE_STATE, "how-to-play"))).toBe("close");
    expect(escapeAction(openDialog(INITIAL_PAUSE_STATE, "signout"))).toBe("close");
    // The pause card's own primary action is "back to coding" — the same
    // gesture, so Esc there minimizes rather than dismissing the card.
    expect(escapeAction(pauseForAgent(INITIAL_PAUSE_STATE, true))).toBe("minimize");
    // Already collapsed: the pill owns the keyboard.
    expect(escapeAction(minimize(INITIAL_PAUSE_STATE))).toBe("none");
  });

  test("transitions never mutate the state they were given", () => {
    const before = { ...INITIAL_PAUSE_STATE };
    openDialog(INITIAL_PAUSE_STATE, "signout");
    minimize(INITIAL_PAUSE_STATE);
    pauseForAgent(INITIAL_PAUSE_STATE, true);
    expect(INITIAL_PAUSE_STATE).toEqual(before);
  });
});

