import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE } from "./tauri-bridge.js";

describe("overlay frame sizes", () => {
  test("match the sizes the README documents", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("expanding is bigger in both directions, never smaller", () => {
    expect(EXPANDED_SIZE.width).toBeGreaterThan(COMPACT_SIZE.width);
    expect(EXPANDED_SIZE.height).toBeGreaterThan(COMPACT_SIZE.height);
  });

  test("the compact frame clears the restored floor", () => {
    expect(COMPACT_SIZE.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(COMPACT_SIZE.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
  });

  /**
   * The reason collapsing has to lower the minimum before setting the size,
   * and restoring has to raise it again: a window still holding the restored
   * floor cannot become a pill.
   */
  test("the pill is smaller than the restored floor", () => {
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });

  test("the browser preview frames the iframe at the same sizes", () => {
    const preview = readFileSync(join(import.meta.dir, "preview.html"), "utf8");
    for (const size of [COMPACT_SIZE, EXPANDED_SIZE, PILL_SIZE]) {
      expect(preview).toContain(String(size.width));
      expect(preview).toContain(String(size.height));
    }
  });
});

