import { describe, expect, test } from "bun:test";
import type { GameEntry, PlayableGame } from "../src/games/registry.js";
import type { StepResult } from "../src/core/game.js";
import {
  appendSavedAction,
  clearSavedGame,
  loadSavedGame,
  randomSeed,
  restoreGame,
  startSavedGame,
  writeSavedGame,
  type SavedGame,
} from "./persistence.js";

/** A `Storage` with no browser attached, plus a switch for a full quota. */
function fakeStorage(): Storage & { failWrites: boolean } {
  const entries = new Map<string, string>();
  return {
    failWrites: false,
    get length() { return entries.size; },
    key(index: number) { return [...entries.keys()][index] ?? null; },
    getItem(key: string) { return entries.get(key) ?? null; },
    setItem(key: string, value: string) {
      if (this.failWrites) throw new Error("quota exceeded");
      entries.set(key, value);
    },
    removeItem(key: string) { entries.delete(key); },
    clear() { entries.clear(); },
  } as Storage & { failWrites: boolean };
}

/**
 * A stand-in shift: `left`/`right` move, `wait` is always refused, and `drop`
