    const entry = stubEntry();
    const saved = savedFor(entry, ["right"]);
    expect(restoreGame({ ...entry, version: "2" }, saved)).toBeNull();
  });

  test("refuses a run recorded for another game", () => {
    const entry = stubEntry();
    expect(restoreGame({ ...entry, id: "other-game" }, savedFor(entry, ["right"]))).toBeNull();
  });

  test("refuses a log containing an action this build dropped", () => {
    const entry = stubEntry();
    // Replaying around a removed action would rebuild a different shift.
    expect(restoreGame(entry, savedFor(entry, ["right", "drop"]))).toBeNull();
  });

  test("a game that cannot be created cannot be resumed", () => {
    const entry = stubEntry();
    expect(restoreGame({ ...entry, create: null }, savedFor(entry, ["right"]))).toBeNull();
  });
});

describe("seeds for a new run", () => {
  test("never hands back the seed it was told to replace", () => {
    // Restart means "start over": replaying the same seed is what resume does.
    let handed = 0;
    const seed = randomSeed(99, () => {
      handed++;
      return handed < 3 ? 99 / 2_147_483_647 : 0.5;
    });
    expect(seed).not.toBe(99);
    expect(handed).toBe(3);
  });

  test("steps off a generator that only ever offers the old seed", () => {
    const seed = randomSeed(99, () => 99 / 2_147_483_647);
    expect(seed).toBe(100);
  });

  test("produces an integer inside the seed range", () => {
    for (const value of [0, 0.5, 0.999999]) {
      const seed = randomSeed(undefined, () => value);
      expect(Number.isInteger(seed)).toBe(true);
      expect(seed).toBeGreaterThanOrEqual(0);
      expect(seed).toBeLessThan(2_147_483_647);
    }
  });
});

