  if (game && !gameEnded) endGame(reason);
  // Whatever the slow writer still owed the record is owed now: the run is
  // leaving the screen, and the menu is about to offer it back.
  flushSavedGame();
  leaveGameScreen();
  pauseState = { ...resumePlay(pauseState), dialog: "none" };
  syncDialogs();
  screen = "menu";
  cursor = -1;
  drawMenu();
}

/**
 * Restart mid-run: a brand-new run of the same game and variation. The stored
 * run is thrown away and the seed is re-randomized — restart means "start
 * over", so only a resume replays a stored seed (README §Session save).
 */
function restartRun(): void {
  const selected = entry;
  if (!selected) return;
  const variationId = activeVariationId();
  const previousSeed = savedGame?.seed;
  if (game && !gameEnded) endGame("restart");
  dropSavedGame();
  const fresh = selected.create?.(variationId);
  if (!fresh) return;
  const seed = randomSeed(previousSeed);
  fresh.reset(seed);
  startRun(selected, variationId, { game: fresh, actions: [], seed });
}

