import { GlobalRegistrator } from "@happy-dom/global-registrator";
import { readFileSync } from "node:fs";

const html = readFileSync("/app/overlay/dist/index.html", "utf8");
GlobalRegistrator.register({ url: "http://localhost/index.html" });
document.write(html);

const tick = (ms = 30) => new Promise((r) => setTimeout(r, ms));

globalThis.requestAnimationFrame = ((cb: FrameRequestCallback) => setTimeout(() => cb(Date.now()), 8) as unknown as number) as typeof requestAnimationFrame;

await import("/app/overlay/app.ts");
await tick(60);

const screen = document.querySelector("#screen")!;
console.log("screen after boot:", (screen as HTMLElement).dataset.screen);
console.log("body mode:", document.body.dataset.mode ?? "(none)");
console.log("game cards:", screen.querySelectorAll("[data-game-index]").length);

// Pick a game.
screen.querySelector<HTMLElement>('[data-game-index="0"]')!.click();
await tick();
console.log("screen after picking a game:", (screen as HTMLElement).dataset.screen);
console.log("variations:", screen.querySelectorAll("[data-variation-index]").length);

// Launch the run.
screen.querySelector<HTMLElement>('[data-variation-index="0"]')!.click();
await tick(120);
console.log("screen after launching:", (screen as HTMLElement).dataset.screen, (screen as HTMLElement).dataset.game);
console.log("saved game:", localStorage.getItem("gamepigeon.arcade.active-game.v1")?.slice(0, 120));

// Play a couple of actions: space starts the shift.
window.dispatchEvent(new KeyboardEvent("keydown", { key: " ", bubbles: true }));
await tick(60);
const savedAfter = JSON.parse(localStorage.getItem("gamepigeon.arcade.active-game.v1") ?? "{}");
console.log("actions recorded:", savedAfter.actions);

// The agent asks for the human back.
window.dispatchEvent(new CustomEvent("gamepigeon:pause"));
await tick();
console.log("pause card hidden:", document.querySelector<HTMLElement>("#return-prompt")!.hidden);

// Back to coding.
document.querySelector<HTMLElement>("#return-code")!.click();
await tick();
console.log("pill mode:", document.body.dataset.mode, "pause card hidden:", document.querySelector<HTMLElement>("#return-prompt")!.hidden);

// And back again.
document.querySelector<HTMLElement>("#pill")!.click();
await tick();
console.log("after pill click, mode:", document.body.dataset.mode ?? "(none)", "pause card hidden:", document.querySelector<HTMLElement>("#return-prompt")!.hidden);

// How to Play, then Esc.
window.dispatchEvent(new CustomEvent("gamepigeon:resume"));
document.querySelector<HTMLElement>("#how-to-play-from-pause")?.click();
await tick();
console.log("help hidden:", document.querySelector<HTMLElement>("#how-to-play")!.hidden);
window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true }));
await tick();
