import { readFileSync } from "node:fs";
import { join } from "node:path";
import { Window } from "happy-dom";
import { PREVIEW_RESIZE_MESSAGE } from "./tauri-bridge.js";
import type { SavedGame } from "./persistence.js";

const SAVE_KEY = "gamepigeon.arcade.active-game.v1";

/** Sizes the app asked the window for, newest last. */
const resizes: { width: number; height: number }[] = [];
/** The arena scene's canvas callbacks, captured at mount. */
let arenaUi: ((action: "menu" | "restart" | "help") => void) | undefined;
let mounts = 0;

mock.module("./restaurant-arena-scene.js", () => ({
  mountRestaurantArenaScene: (
    _parent: HTMLElement,
    _state: unknown,
    _onAction: (action: string) => void,
    onUi: (action: "menu" | "restart" | "help") => void,
  ) => {
    arenaUi = onUi;
    mounts++;
    return { render() {}, setWorkerStatus() {}, destroy() {} };
  },
}));

function installDom(): void {
  const html = readFileSync(join(import.meta.dir, "dist", "index.html"), "utf8")
    // The shell loads app.js itself; this test imports the module directly.
    .replace(/<script[\s\S]*?<\/script>/g, "");
  const win = new Window({ url: "http://localhost/index.html", width: 600, height: 850 });
  win.document.write(html);
  const globals = [
    "window", "document", "navigator", "location", "localStorage", "sessionStorage",
    "Element", "HTMLElement", "HTMLInputElement", "HTMLSelectElement", "HTMLButtonElement",
    "HTMLTextAreaElement", "HTMLOListElement", "Node", "Event", "CustomEvent",
    "KeyboardEvent", "MouseEvent", "PointerEvent", "getComputedStyle",
    "requestAnimationFrame", "cancelAnimationFrame",
  ] as const;
  for (const key of globals) {
    (globalThis as unknown as Record<string, unknown>)[key] = (win as unknown as Record<string, unknown>)[key];
  }
  // Nothing here talks to a server: the preview transport only reaches for one
  // when it wants a live worker model, and this crew is deterministic.
  globalThis.fetch = (() => Promise.reject(new Error("offline"))) as typeof fetch;
  win.addEventListener(PREVIEW_RESIZE_MESSAGE, (event) => {
    const detail = (event as CustomEvent<{ width: number; height: number }>).detail;
