const settle = (ms = 40) => new Promise((resolve) => setTimeout(resolve, ms));

const screenEl = () => document.querySelector<HTMLElement>("#screen")!;
const click = (selector: string) => {
  const target = document.querySelector<HTMLElement>(selector);
  expect(target, `missing ${selector}`).not.toBeNull();
  target!.click();
};
const press = (key: string) => window.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true }));
const host = (name: string, detail?: unknown) => window.dispatchEvent(new CustomEvent(name, { detail }));
const save = (): SavedGame | null => {
  const raw = localStorage.getItem(SAVE_KEY);
  return raw ? (JSON.parse(raw) as SavedGame) : null;
};
