describe("starting a run", () => {
  test("boots onto the menu at the compact frame", () => {
    expect(screenEl().dataset.screen).toBe("menu");
    expect(document.querySelectorAll("[data-game-index]").length).toBeGreaterThan(0);
    expect(lastResize()).toEqual({ width: 600, height: 850 });
  });

  test("picking a game offers its variations", () => {
    click('[data-game-index="0"]');
    expect(screenEl().dataset.screen).toBe("variations");
    expect(document.querySelectorAll("[data-variation-index]").length).toBeGreaterThan(0);
  });

