    expect(save()!.actions.length).toBe(held);
  });

  test("Continue playing hands the shift back", async () => {
    click("#continue-game");
    expect(hidden("#return-prompt")).toBe(true);
    const resumed = save()!.actions.length;
    await settle(300);
    expect(save()!.actions.length).toBeGreaterThan(resumed);
  });

  test("a host resume also releases the hold", async () => {
    host("gamepigeon:pause");
    await settle();
    expect(hidden("#return-prompt")).toBe(false);
    host("gamepigeon:resume");
    await settle();
    expect(hidden("#return-prompt")).toBe(true);
  });
});

describe("the window chrome", () => {
  test("minimizing collapses to the pill and holds the run", async () => {
    click("#hide");
    await settle();
    expect(document.body.dataset.mode).toBe("pill");
    expect(lastResize()).toEqual({ width: 144, height: 48 });
    const parked = save()!.actions.length;
    await settle(300);
    expect(save()!.actions.length).toBe(parked);
  });

  test("the pill restores the frame it came from", async () => {
    click("#pill");
    await settle();
    expect(document.body.dataset.mode).toBeUndefined();
    expect(lastResize()).toEqual({ width: 600, height: 850 });
    expect(screenEl().dataset.screen).toBe("game");
  });

  test("Esc is the same gesture as the minimize button", async () => {
    press("Escape");
    await settle();
    expect(document.body.dataset.mode).toBe("pill");
    click("#pill");
    await settle();
    expect(document.body.dataset.mode).toBeUndefined();
  });

  test("the resize toggle swaps between the two documented frames", async () => {
    const resize = document.querySelector<HTMLButtonElement>("#resize")!;
    expect(resize.textContent).toBe("↗");
    resize.click();
    await settle();
    expect(lastResize()).toEqual({ width: 830, height: 900 });
    expect(resize.textContent).toBe("↙");
    resize.click();
    await settle();
    expect(lastResize()).toEqual({ width: 600, height: 850 });
    expect(resize.textContent).toBe("↗");
  });
});

describe("the cards over the board", () => {
  test("How to Play opens over the shift and Esc closes it", async () => {
    arenaUi?.("help");
    await settle();
    expect(hidden("#how-to-play")).toBe(false);
    const reading = save()!.actions.length;
    await settle(300);
    expect(save()!.actions.length).toBe(reading);
    press("Escape");
    await settle();
    // Esc dismissed the card rather than minimizing, since a card was up.
    expect(hidden("#how-to-play")).toBe(true);
    expect(document.body.dataset.mode).toBeUndefined();
  });

  test("closing How to Play opened from the pause card leaves the run held", async () => {
    host("gamepigeon:pause");
    await settle();
    click("#how-to-play-from-pause");
    expect(hidden("#how-to-play")).toBe(false);
    click("#how-to-play-close");
    expect(hidden("#how-to-play")).toBe(true);
    expect(hidden("#return-prompt")).toBe(false);
    const held = save()!.actions.length;
    await settle(300);
    expect(save()!.actions.length).toBe(held);
    click("#continue-game");
  });
});

describe("ending and resuming a shift", () => {
  let ended: SavedGame;

  test("ending a shift returns to the menu with the run still resumable", async () => {
    ended = save()!;
    expect(ended.actions.length).toBeGreaterThan(1);
    arenaUi?.("menu");
    await settle();
    expect(screenEl().dataset.screen).toBe("menu");
    expect(save()).toEqual(ended);
    expect(document.querySelector("[data-resume]")).not.toBeNull();
  });

  test("resuming replays the stored seed and actions", async () => {
    click("[data-resume]");
    await settle();
    expect(screenEl().dataset.screen).toBe("game");
    const resumed = save()!;
    expect(resumed.seed).toBe(ended.seed);
    expect(resumed.actions).toEqual(ended.actions);
  });

  test("restarting throws the run away and deals a different night", async () => {
    const before = save()!;
    press("r");
    await settle();
    const restarted = save()!;
    expect(restarted.seed).not.toBe(before.seed);
    expect(restarted.actions).toEqual([]);
    expect(screenEl().dataset.screen).toBe("game");
  });
});

describe("the host's own launches", () => {
  test("a launch event starts the named game and variation", async () => {
    arenaUi?.("menu");
    await settle();
    host("gamepigeon:launch", { game: "restaurant-arena", variation: "training-shift" });
    await settle();
    expect(screenEl().dataset.screen).toBe("game");
    expect(save()!.variationId).toBe("training-shift");
  });

  test("an unknown game leaves the player where they are", async () => {
    const before = save()!;
    host("gamepigeon:launch", { game: "no-such-game" });
    await settle();
    expect(save()).toEqual(before);
  });

  test("a new session resets to the menu without discarding the run", async () => {
    const before = save()!;
    host("gamepigeon:reset");
    await settle();
    expect(screenEl().dataset.screen).toBe("menu");
    expect(save()).toEqual(before);
  });
});

describe("signing out", () => {
  test("the confirmation can be dismissed", () => {
    click("#account-chip");
    expect(hidden("#signout-prompt")).toBe(false);
    click("#signout-cancel");
    expect(hidden("#signout-prompt")).toBe(true);
  });
});

