  mountRestaurantArenaScene: (
    _parent: HTMLElement,
    _state: unknown,
    _onAction: (action: string) => void,
    onUi: (action: "menu" | "restart" | "help") => void,
  ) => {
    arenaUi = onUi;
    mounts++;
    return { render() {}, setWorkerStatus() {}, destroy() {} };
  },
}));

function installDom(): void {
  const html = readFileSync(join(import.meta.dir, "dist", "index.html"), "utf8")
    // The shell loads app.js itself; this test imports the module directly.
    .replace(/<script[\s\S]*?<\/script>/g, "");
  const win = new Window({ url: "http://localhost/index.html", width: 600, height: 850 });
  win.document.write(html);
