    "window", "document", "navigator", "location", "localStorage", "sessionStorage",
    "Element", "HTMLElement", "HTMLInputElement", "HTMLSelectElement", "HTMLButtonElement",
    "HTMLTextAreaElement", "HTMLOListElement", "Node", "Event", "CustomEvent",
    "KeyboardEvent", "MouseEvent", "PointerEvent", "getComputedStyle",
    "requestAnimationFrame", "cancelAnimationFrame",
  ] as const;
  for (const key of globals) {
    (globalThis as unknown as Record<string, unknown>)[key] = (win as unknown as Record<string, unknown>)[key];
  }
  // Nothing here talks to a server: the preview transport only reaches for one
  // when it wants a live worker model, and this crew is deterministic.
  globalThis.fetch = (() => Promise.reject(new Error("offline"))) as typeof fetch;
  win.addEventListener(PREVIEW_RESIZE_MESSAGE, (event) => {
    const detail = (event as CustomEvent<{ width: number; height: number }>).detail;
    resizes.push({ width: detail.width, height: detail.height });
