arguments.new_string:
const hidden = (selector: string) => document.querySelector<HTMLElement>(selector)!.hidden;
/**
 * The actions the engine actually accepted, newest last, read off the run's
 * recording journal — which is written on every step, where the resume record
 * is written on a slow timer.
 */
function landed(): string[] {
  for (let index = 0; index < localStorage.length; index++) {
    const key = localStorage.key(index);
    if (!key?.startsWith("gamepigeon:recording:")) continue;
    const trace = JSON.parse(localStorage.getItem(key)!) as { actions: { action: string }[] };
    return trace.actions.map(({ action }) => action);
  }
  return [];
}

