/** Let queued microtasks, timers and the mount's rAF pair land. */
const settle = (ms = 40) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Longer than one tick at the fastest cadence (3s / 4×), so "the clock did not
 * advance" means the clock was actually held rather than merely slow.
 */
const HOLD_MS = 1_200;

async function waitFor(what: string, ready: () => boolean, timeoutMs = 5_000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (ready()) return;
    await settle(25);
  }
  throw new Error(`timed out waiting for ${what}`);
}

