describe("the cards over the board", () => {
  test("How to Play opens over the shift and Esc closes it", async () => {
    arenaUi?.("help");
    await settle();
    expect(hidden("#how-to-play")).toBe(false);
    const reading = landed().length;
    await settle(HOLD_MS);
    expect(landed().length).toBe(reading);
    press("Escape");
    await settle();
    // Esc dismissed the card rather than minimizing, since a card was up.
    expect(hidden("#how-to-play")).toBe(true);
    expect(document.body.dataset.mode).toBeUndefined();
  });

  test("closing How to Play opened from the pause card leaves the run held", async () => {
    host("gamepigeon:pause");
    await settle();
    click("#how-to-play-from-pause");
    expect(hidden("#how-to-play")).toBe(false);
    click("#how-to-play-close");
    expect(hidden("#how-to-play")).toBe(true);
    expect(hidden("#return-prompt")).toBe(false);
    const held = landed().length;
    await settle(HOLD_MS);
    expect(landed().length).toBe(held);
    click("#continue-game");
  });
});

describe("ending and resuming a shift", () => {
  let ended: SavedGame;

  test("ending a shift returns to the menu with the run still resumable", async () => {
    expect(landed().length).toBeGreaterThan(1);
    // The arena's own on-canvas menu control, the pause card's Menu button and
    // a host reset all land here.
    arenaUi?.("menu");
    await settle();
    expect(screenEl().dataset.screen).toBe("menu");
    // Leaving settles whatever the slow writer still owed the record.
    ended = save()!;
    expect(ended.actions.length).toBeGreaterThan(1);
    expect(document.querySelector("[data-resume]")).not.toBeNull();
  });

  test("resuming replays the stored seed and actions", async () => {
    click("[data-resume]");
    await settle();
    expect(screenEl().dataset.screen).toBe("game");
    const resumed = save()!;
    expect(resumed.seed).toBe(ended.seed);
    expect(resumed.actions).toEqual(ended.actions);
  });

  test("restarting throws the run away and deals a different night", async () => {
    const before = save()!;
    press("r");
    await settle();
    const restarted = save()!;
    expect(restarted.seed).not.toBe(before.seed);
    expect(restarted.actions).toEqual([]);
    expect(screenEl().dataset.screen).toBe("game");
  });
});

describe("the host's own launches", () => {
  test("a launch event starts the named game and variation", async () => {
    arenaUi?.("menu");
    await settle();
    host("gamepigeon:launch", { game: "restaurant-arena", variation: "quiet-tuesday" });
    await settle();
    expect(screenEl().dataset.screen).toBe("game");
    expect(save()!.variationId).toBe("quiet-tuesday");
  });

  test("an unknown game leaves the player where they are", async () => {
    const before = save()!;
    host("gamepigeon:launch", { game: "no-such-game" });
    await settle();
    expect(screenEl().dataset.screen).toBe("game");
    expect(save()!.seed).toBe(before.seed);
  });

  test("a new session resets to the menu without discarding the run", async () => {
    const before = save()!;
    host("gamepigeon:reset");
    await settle();
    expect(screenEl().dataset.screen).toBe("menu");
    expect(save()!.seed).toBe(before.seed);
    expect(save()!.variationId).toBe(before.variationId);
    expect(document.querySelector("[data-resume]")).not.toBeNull();
  });
});

