describe("running out the night", () => {
  test("the shift ends on a debrief that names the run, with nothing left to resume", async () => {
    host("gamepigeon:launch", { game: "restaurant-arena", variation: "tutorial-shift" });
    await settle();
    press(" ");
    // `t` is the engine's manual tick, so the whole night runs without waiting
    // out the clock. The cap is a stuck-shift guard, not an expected length.
    for (let step = 0; step < 2_000 && !document.querySelector(".game-end-overlay"); step++) press("t");
    await settle();
    const card = document.querySelector<HTMLElement>(".game-end-overlay");
    expect(card).not.toBeNull();
    expect(card!.querySelector(".game-end-title")!.textContent).toMatch(/Shift (complete|over)/);
    // The id a tester can read back to match their run against what arrived.
    expect(card!.querySelector("[data-session-id]")!.textContent).toMatch(/^game_/);
    // A finished shift is not resumable, so the save is gone.
    expect(save()).toBeNull();
    expect(screenEl().dataset.screen).toBe("game");
  });

  test("the debrief's own controls play again and go back to the menu", async () => {
    click('[data-end="restart"]');
    await settle();
    expect(document.querySelector(".game-end-overlay")).toBeNull();
    expect(save()!.actions).toEqual([]);
    click('[data-restart]');
    await settle();
    arenaUi?.("menu");
    await settle();
    expect(screenEl().dataset.screen).toBe("menu");
  });
});

